def get_career_roadmap(target_role: str, current_skills: list = None) -> dict:
    role_lower = target_role.lower().strip()

    matched = None
    for key in CAREER_ROADMAPS:
        if key in role_lower or role_lower in key or any(word in role_lower for word in key.split()):
            matched = key
            break

    if not matched:
        matched = "full stack developer"

    roadmap = CAREER_ROADMAPS[matched].copy()

    # Mark skills user already has
    if current_skills:
        current_lower = [s.lower() for s in current_skills]
        for step in roadmap["steps"]:
            step["completed_skills"] = [s for s in step["skills"] if s.lower() in current_lower]
            step["remaining_skills"] = [s for s in step["skills"] if s.lower() not in current_lower]
            step["is_complete"] = len(step["remaining_skills"]) == 0

    return roadmap
